 65→	public static final char SYMBOL_COLON = ':';
 66→	public static final Pattern PTN_NUMBER = 
 67→		//숫자판단 패턴
 68→		Pattern.compile(
 69→			"^(" //규칙시작 (앞공백 없음)
 70→				+ "("
 71→					+ "("
 72→						+ "([0-9]{0,3}([,][0-9]{3})*)" + "|"  //3자리(,) 단위웃자의 연속이거나
 73→						+ "([0-9]+)" //순수숫자의 연속이거나
 74→					+ ")"
 75→					+ "([.][0-9]+)*" //소숫점이 나온다면 뒤에는 순수숫자의 연속이어야 함
 76→				+ ")"
 77→			+ ")"
 78→			+ "("
 79→				+ "[:]" // : 뒤에 같은 규칙으로 숫자가 나열되는 경우 (1,000:10.5 등)
 80→				+ "("
 81→					+ "("
 82→						+ "([0-9]{0,3}([,][0-9]{3})*)" + "|"
 83→						+ "([0-9]+)"
 84→					+ ")"
 85→					+ "([.][0-9]+)*"
 86→				+ ")"
 87→			+ "){0,1}" //없거나 한번등장
 88→			+ "$" //규칙끝 (뒷공백 없음)
 89→		);
