package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.product.AnalyzerOption;

import java.util.List;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;
import static com.danawa.search.analysis.product.ProductNameTokenizer.JAPANESE;

public class RuleTwo extends Rule {

    public RuleTwo(Entry entry, boolean fullExtract, AnalyzerOption option) {
        super(entry, fullExtract, option);
    }

    @Override
    public void apply(List<RuleEntry> queue) {
        // 2차 가공, 변경타입을 생성한다 ( NUMBER_TRANS 등 )
        for (int qinx = 0; qinx < queue.size(); qinx++) {
            RuleEntry currentEntry = queue.get(qinx);

            if (isFullStringEntry(currentEntry)) {
                continue;
            }

            // 다다음 인덱스가 존재할 경우
            if (existNextNextIndex(queue, qinx)) {
                RuleEntry nextEntry = queue.get(qinx + 1);
                RuleEntry nextNextEntry = queue.get(qinx + 2);

                // 변경 가능한 대상일 경우
                if (isChangeableNumber(currentEntry, nextEntry, nextNextEntry)) {
                    RuleEntry cloneEntry = currentEntry.clone();
                    currentEntry.length += nextEntry.length + nextNextEntry.length;
                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length;

                    // 숫자 패턴여부 체크해서 NUMBER_TRANS 타입으로 변환
                    if (isNumberPattern(currentEntry)) {
                        qinx = changeTransNumber(queue, qinx, currentEntry);
                        continue;
                    } else {
                        restoreEntry(currentEntry, cloneEntry);
                    }
                }
            }

            // 다음 인덱스가 존재할 경우
            if (existNextIndex(queue, qinx)) {
                qinx = modifyEtc(queue, qinx, currentEntry);
            }
        }
        logger.trace("2nd process complete / queue:{}", queue);
    }

    private int modifyEtc(List<RuleEntry> queue, int qinx, RuleEntry currentEntry) {
        // ALPHA, NUMBER, JAPAN, CHINA 변경
        RuleEntry nextEntry = queue.get(qinx + 1);
        if (isConnectEntry(currentEntry, nextEntry)) {
            qinx = ruleAlterType(queue, qinx, currentEntry, nextEntry);
        }
        return qinx;
    }

    private int ruleAlterType(List<RuleEntry> queue, int qinx, RuleEntry currentEntry, RuleEntry nextEntry) {
        if (isAlphaEntry(currentEntry) && isAlphaEntry(nextEntry)) {
            setEntryType(queue, qinx, ALPHA);
        } else if (isNumberEntry(currentEntry) && isNumberEntry(nextEntry)) {
            setEntryType(queue, qinx, NUMBER);
        } else if (isJapanOrChina(currentEntry, nextEntry)) {
            // 외래어 포용성이 높은 문자로 이동 ( 중국어 처럼 보인다 하더라도 일본어가 섞인 블럭이면 일본어 )
            qinx = setEntryTypeJapanese(queue, qinx, currentEntry, nextEntry);
        }
        return qinx;
    }

    private int setEntryTypeJapanese(List<RuleEntry> queue, int qinx, RuleEntry currentEntry, RuleEntry nextEntry) {
        currentEntry.length += nextEntry.length;
        currentEntry.endOffset = nextEntry.endOffset;
        currentEntry.type = JAPANESE;
        queue.remove(qinx + 1);
        qinx--;
        return qinx;
    }

    private boolean isJapanOrChina(RuleEntry currentEntry, RuleEntry nextEntry) {
        return isJapanese(currentEntry) && isJapanese(nextEntry)
                || (isChinese(currentEntry) && isChinese(nextEntry))
                || (isJapanese(currentEntry) && isChinese(nextEntry));
    }

    private void setEntryType(List<RuleEntry> queue, int qinx, String type) {
        RuleEntry currentEntry;
        currentEntry = Entry.mergeQueueQuery(qinx + 2, 2, queue, null);
        if (currentEntry != null) {
            currentEntry.type = type;
        }
    }

    private boolean isNumberPattern(RuleEntry currentEntry) {
        return PTN_NUMBER.matcher(currentEntry.makeTerm(null)).find();
    }

    private boolean isConnectEntry(RuleEntry currentEntry, RuleEntry nextEntry) {
        return isConnected(currentEntry, nextEntry) && currentEntry.length > 0 && nextEntry.length > 0;
    }

    private void restoreEntry(RuleEntry currentEntry, RuleEntry cloneEntry) {
        currentEntry.length = cloneEntry.length;
        currentEntry.endOffset = cloneEntry.endOffset;
    }

    private int changeTransNumber(List<RuleEntry> queue, int qinx, RuleEntry currentEntry) {
        currentEntry.type = NUMBER_TRANS;
        queue.remove(qinx + 2);
        queue.remove(qinx + 1);
        qinx--;
        return qinx;
    }

    private boolean isChangeableNumber(RuleEntry currentEntry, RuleEntry nextEntry, RuleEntry nextNextEntry) {
        return isEntryType(currentEntry, NUMBER, NUMBER_TRANS)
                && isSymbolEntry(nextEntry) && nextEntry.length == 1
                && isNumberEntry(nextNextEntry)
                && isConnected(currentEntry, nextEntry)
                && isConnected(nextEntry, nextNextEntry)
                && isAvailSymbolChar(nextEntry.buf[nextEntry.start]);
    }

    private boolean isAvailSymbolChar(char c) {
        return containsChar(AVAIL_SYMBOLS_INNUMBER, c);
    }
}

