package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.dict.SetDictionary;
import com.danawa.search.analysis.dict.SynonymDictionary;
import com.danawa.search.analysis.product.AnalyzerOption;
import com.danawa.util.CharVector;

import java.util.List;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;
import static com.danawa.search.analysis.product.ProductNameTokenizer.NUMBER;

public class RuleThree extends Rule {

    public RuleThree(Entry entry, boolean fullExtract, AnalyzerOption option,
                     SetDictionary unitDictionary, SynonymDictionary unitSynonymDictionary) {
        super(entry, fullExtract, option);
        this.unitDictionary = unitDictionary;
        this.unitSynonymDictionary = unitSynonymDictionary;
    }

    @Override
    public void apply(List<RuleEntry> queue) {
        RuleEntry nextNextEntry = null;

        // 3차 가공, 단위명을 색출한다.
        for (int qinx = 0; qinx < queue.size(); qinx++) {
            RuleEntry currentEntry = queue.get(qinx);
            if (isFullStringEntry(currentEntry)) {
                continue;
            }

            if (existNextIndex(queue, qinx)) {
                RuleEntry nextEntry = queue.get(qinx + 1);

                // 숫자가 포함된 엔트리일 경우
                if (isConnectedNumberEntry(currentEntry, nextEntry)) {
                    nextNextEntry = getUnit(queue, nextNextEntry, qinx, currentEntry, nextEntry);
                }
            }
        }

        logger.trace("3rd process complete / queue:{}", queue);
    }

    private RuleEntry getUnit(List<RuleEntry> queue, RuleEntry nextNextEntry, int qinx, RuleEntry currentEntry, RuleEntry nextEntry) {
        CharVector unitCandidate = new CharVector();
        unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length);

        int findInx = 5;
        boolean foundUnit = false;
        for (; findInx > 0; findInx--) {
            if (qinx + findInx < queue.size()) {
                RuleEntry prevEntry = queue.get(qinx + findInx);

                // 길이가 0 이거나 한글 엔트리 제외
                if (prevEntry.length == 0 || (findInx > 1 && isHangulEntry(prevEntry))) { continue; }

                // 단위명 길이 추출
                int unitLength = getUnitLength(nextEntry, prevEntry);

                // 단위명 사전 제한 길이 이하
                if (unitLength <= MAX_UNIT_LENGTH) {
                    if (nextEntry.buf.length >= nextEntry.start + unitLength) {
                        unitCandidate.init(nextEntry.buf, nextEntry.start, unitLength);

                        // 단위명 사전에서 검색
                        if (findUnitDictionary(unitCandidate, getUniType(unitCandidate))) {
                            foundUnit = true;
                            break;
                        }
                    }
                }
            }
        }

        // 단위명이 발견되었을 경우
        if (foundUnit) {
            nextNextEntry = getRuleEntry(queue, nextNextEntry, qinx, currentEntry, nextEntry, unitCandidate, findInx);
        }
        return nextNextEntry;
    }

    private int getUnitLength(RuleEntry nextEntry, RuleEntry prevEntry) {
        int unitLength;
        if (isSameBuffer(nextEntry, prevEntry)) {
            unitLength = prevEntry.start + prevEntry.length - nextEntry.start;
        } else {
            // PrevEntry, NextEntry 버퍼가 다르다면, 서로의 포지션은 영향을 주지 않는다.
            unitLength = nextEntry.length;
        }
        return unitLength;
    }

    private boolean isSameBuffer(RuleEntry nextEntry, RuleEntry prevEntry) {
        return prevEntry.buf == nextEntry.buf;
    }

    private boolean isConnectedNumberEntry(RuleEntry currentEntry, RuleEntry nextEntry) {
        return isConnected(currentEntry, nextEntry) && (isNumberEntry(currentEntry) || isNumberTransEntry(currentEntry));
    }

    private RuleEntry getRuleEntry(List<RuleEntry> queue, RuleEntry nextNextEntry, int qinx, RuleEntry currentEntry, RuleEntry nextEntry, CharVector unitCandidate, int findInx) {
        String typePrev;
        String unitType = getUniType(unitCandidate);
        CharSequence[] units = null;
        if (unitSynonymDictionary != null) {
            units = unitSynonymDictionary.get(unitCandidate);
        }
        char tempch1 = 0x0;
        if (currentEntry.start > entry.start) {
            tempch1 = currentEntry.buf[currentEntry.start - 1];
        }

        typePrev = setTypePrev(queue, qinx);

        /* findUnit에서 텀조합이 글자 줄임 없이 정확하게 매칭된 경우 */
        if (isAllMatchTerm(queue, qinx, nextEntry, unitCandidate, findInx)) {
            // 숫자 이전글자가 영문이며, 단위명 자투리도 영문인 경우 모델명 우선으로 인식, 예:a1024mm
            if (isAlphaWithUnit(typePrev, unitType, tempch1)) {
                // 단위명의 동의어가 있다면 처리한다.
                processUnitSynonym(queue, qinx, currentEntry, nextEntry, unitCandidate, findInx, unitType, units);
            }
        } else if (isReduceTerm(nextEntry, unitCandidate)) {
            /* findUnit에 의해 글자 줄임이 발생한 경우 */
            // 단위명이 영문이며, 단위명 자투리도 영문인 경우 모델명으로 인식 예:1024mmcc
            // 뒷단어가 바로 붙어있어야 인정. 공백이 있다면 불가.
            nextNextEntry = getXNextEntry(queue, nextNextEntry, qinx);

            // 모델명 우선
            currentEntry.modifiable = true;
            nextEntry.modifiable = true;
        }
        return nextNextEntry;
    }

    private String setTypePrev(List<RuleEntry> queue, int qinx) {
        String typePrev;
        if (qinx > 0) {
            typePrev = queue.get(qinx - 1).type;
        } else {
            typePrev = null;
        }
        return typePrev;
    }

    private RuleEntry getXNextEntry(List<RuleEntry> queue, RuleEntry nextNextEntry, int qinx) {
        if (qinx + 2 < queue.size()){
            nextNextEntry = queue.get(qinx + 2);
        }
        return nextNextEntry;
    }

    private void processUnitSynonym(List<RuleEntry> queue, int qinx, RuleEntry currentEntry, RuleEntry nextEntry, CharVector unitCandidate, int findInx, String unitType, CharSequence[] units) {
        Entry.modifyRuleEntry(fullExtract, option, currentEntry, nextEntry, unitCandidate, units, unitType);
        logger.trace("currentEntry:{} / SYN:{}", currentEntry, currentEntry.synonym);
        // 1,000과 같은 NUMBER_TRANS는 지우면 안됨
        boolean isNumberTransEntry = false;
        for(RuleEntry entry : currentEntry.subEntry){
            if (entry.type == NUMBER_TRANS) {
                isNumberTransEntry = true;
                break;
            }
        }
        for (; findInx >= 1; findInx--) {
            // 여기서 UNIT은 모두 한글 단위, 한글 단위는 살려야하므로 not remove
            if(!isNumberTransEntry && (currentEntry.type != UNIT)){
                queue.remove(qinx + findInx);
            } else if(option.useForQuery()){
                queue.remove(qinx + findInx);
            }
        }
    }

    private boolean isAlphaWithUnit(String typePrev, String unitType, char tempch1) {
        return (unitType == ALPHA && (typePrev == UNIT || typePrev == UNIT_ALPHA)) ||
                !(getType(tempch1) == ALPHA && unitType == ALPHA);
    }

    private boolean isReduceTerm(RuleEntry nextEntry, CharVector unitCandidate) {
        return nextEntry.buf.length > nextEntry.start + unitCandidate.length();
    }

    private boolean isAllMatchTerm(List<RuleEntry> queue, int qinx, RuleEntry nextEntry, CharVector unitCandidate, int findInx) {
        return (findInx == 1 && unitCandidate.length() == nextEntry.length) ||
                (findInx > 1 && (qinx + findInx) < queue.size() && unitCandidate.length() ==
                        queue.get(qinx + findInx).endOffset - nextEntry.startOffset);
    }

    private boolean findUnitDictionary(CharVector key, String type) {
        key.ignoreCase();
        if (isEquals(type, ALPHA) || isEquals(type, SYMBOL)) {
            if (key.length() > MAX_UNIT_LENGTH) {
                key.length(MAX_UNIT_LENGTH);
            }
            if (checkUnitDictionary(key)) return true;
            key.length(key.length() - 1);
            return false;
        } else {
            return isContainUnitDictionary(key);
        }
    }

    private boolean checkUnitDictionary(CharVector key) {
        for (int len = key.length(); len >= 0; len--) {
            key.length(len);
            if (isContainUnitDictionary(key)) return true;
        }
        return false;
    }

    private boolean isContainUnitDictionary(CharVector key) {
        return unitDictionary != null && unitDictionary.set().contains(key);
    }
}

