117→        logger.trace("4th process complete / queue:{}", queue);
118→    }
119→
120→    private void ruleRemainTerm(List<RuleEntry> queue, ContinuousOption remainOption) {
121→        remainOption.typeContinuousMerge++;
122→        // 마지막 특수기호는 버린다.
123→        if (remainOption.type == SYMBOL) {
124→            queue.remove(queue.size() - 1);
125→            remainOption.typeContinuousMerge--;
126→        }
127→        if (remainOption.typeContinuousMerge > 1) {
128→            List<RuleEntry> subQueue = null;
129→            if (fullExtract) {
130→                subQueue = new ArrayList<>();
131→            }
132→            logger.trace("merging.. {} / {} / {}", remainOption.typeContinuousMerge, queue, subQueue);
133→            RuleEntry entry;
134→            if(!option.useForQuery()){
135→                // 색인 시
136→                entry = Entry.mergeQueueIndex(queue.size(), remainOption.typeContinuousMerge, queue, subQueue);
137→            } else {
138→                // 검색 시
139→                entry = Entry.mergeQueueQuery(queue.size(), remainOption.typeContinuousMerge, queue, subQueue);
140→            }
141→
142→            if (entry != null) {
143→                if (entry.type == null) { entry.type = MODEL_NAME; }
144→                logger.trace("subQueue:{}", subQueue);
145→
146→                if (fullExtract) {
147→                    logger.trace("## MERGE_2 : {} : {}", entry, subQueue);
148→                    Entry.mergeSubQueue(entry, subQueue, option, unitDictionary);
149→                    if (subQueue.size() > 1) {
150→                        entry.subEntry = subQueue;
151→                    }
152→                    logger.trace("entry:{} / subQueue:{}", entry, entry.subEntry);
153→                }
154→            }
155→        }
156→    }
157→
158→    private int combineUsedModelNameTerm(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
159→        remainOption.typeContinuousMerge++;
160→        // 마지막 특수기호는 버린다.
161→        if (remainOption.type == SYMBOL) {
162→            // 독립기호가 아닌경우에만 버리도록
163→            if (!(currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_STANDALONE, currentEntry.buf[currentEntry.start]))) {
164→                queue.remove(qinx);
165→            }
166→        }
167→
168→        if (remainOption.typeContinuousMerge > 1) {
169→            List<RuleEntry> subQueue = null;
170→            if (fullExtract) {
171→                subQueue = new ArrayList<>();
172→            }
173→            logger.trace("merging..qinx:{} / tcont:{}", qinx, remainOption.typeContinuousMerge);
174→            RuleEntry entry;
175→            if(!option.useForQuery()){
176→                // 색인 시
177→                entry = Entry.mergeQueueIndex(qinx, remainOption.typeContinuousMerge, queue, subQueue);
178→            } else {
179→                // 검색 시
180→                entry = Entry.mergeQueueQuery(qinx, remainOption.typeContinuousMerge, queue, subQueue);
181→            }
182→
183→            if (entry != null) {
184→                if (entry.type == null) { entry.type = MODEL_NAME; }
185→                logger.trace("qinx:{} / typeContinuousMerge:{} / overIndex:{}", qinx, remainOption.typeContinuousMerge, remainOption.overIndex);
186→                qinx -= remainOption.typeContinuousMerge;
187→                logger.trace("qinx:{}", qinx);
188→                qinx -= remainOption.overIndex;
189→                if (fullExtract) {
190→                    logger.trace("## MERGE_1 : {} : {}", entry, subQueue);
191→                    Entry.mergeSubQueue(entry, subQueue, option, unitDictionary);
192→                    if (subQueue.size() > 1) {
193→                        entry.subEntry = subQueue;
194→                    }
195→                    logger.trace("entry:{} / subQueue:{}", entry, entry.subEntry);
196→                    logger.trace("## Q[{}] : {}", qinx, queue);
197→                }
198→            }
199→        }
200→        return qinx;
201→    }
202→
203→    private void ruleUnitAlphaEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
204→        RuleEntry prevEntry = null;
205→        RuleEntry nextEntry = null;
206→        if (qinx > 0) {
207→            prevEntry = queue.get(qinx - 1);
208→        }
209→        if (qinx + 1 < queue.size()) {
210→            nextEntry = queue.get(qinx + 1);
211→        }
212→        if (prevEntry != null && (currentEntry.start != prevEntry.start + prevEntry.length)) {
213→            // 붙이지 않는다.
214→            remainOption.typeContinuous = 0;
215→            remainOption.isContinue = false;
216→        } else if(prevEntry != null && nextEntry != null
217→                && (isSymbolEntry(prevEntry) && !(isAlphaEntry(nextEntry) || isNumberEntry(nextEntry))
218→                || isSymbolEntry(nextEntry) && !(isAlphaEntry(prevEntry) || isNumberEntry(prevEntry)))
219→        ) {
220→            // 단위명 앞 뒤로 기호일 경우는 일단 모델명에서 제외, 단위명 우선.
221→            // 단 단위가 연결자일 경우는 모델명 우선.
222→            // 한쪽이라도 - 연결자가 발견되면 다시 모델명으로 인식.
223→            if (!(prevEntry.buf[prevEntry.start] == '-' || nextEntry.buf[nextEntry.start] == '-')) {
224→                currentEntry.modifiable = false;
225→                if (remainOption.typeContinuous > 0) {
226→                    logger.trace("model name cancel 6");
227→                    breakContinuous(remainOption, remainOption.typeContinuous - 1);
228→                } else {
229→                    remainOption.typeContinuous = 0;
230→                    remainOption.isContinue = true;
231→                }
232→            } else {
233→                remainOption.isContinue = false;
234→            }
235→        }
236→    }
237→
238→    private int ruleSymbolEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
239→        if (currentEntry.buf[currentEntry.start] == '/' && option.useForQuery()) {
240→            // 숫자 사이의 / 는 삭제
241→            if (qinx > 0 && qinx + 1 < queue.size()) {
242→                RuleEntry prevEntry = queue.get(qinx - 1);
243→                RuleEntry nextEntry = queue.get(qinx + 1);
244→                if (isConnected(prevEntry ,currentEntry) && isConnected(currentEntry, nextEntry)
245→                        && (isNumberEntry(prevEntry) && isNumberEntry(nextEntry))) {
246→                    // 단일숫자일 경우에만 / 삭제
247→                    if (remainOption.typeContinuous < 2) {
248→                        logger.trace("model name cancel 3");
249→                        qinx = cancelModelName(queue, remainOption, qinx, prevEntry, nextEntry);
250→                    }
251→                }
252→            }
253→        } else if (currentEntry.buf[currentEntry.start] == '+' && option.useForQuery()) {
254→            // + 로 이어진 모델명들은 취소한다.
255→            if (qinx > 0 && qinx + 1 < queue.size()) {
256→                RuleEntry prevEntry = queue.get(qinx - 1);
257→                RuleEntry nextEntry = queue.get(qinx + 1);
258→                if (isConnected(prevEntry, currentEntry) && isConnected(currentEntry, nextEntry)) {
259→                    logger.trace("model name cancel 4 / {}:{}", remainOption.typeContinuous, remainOption.typeContinuousMerge);
260→                    cancelModelName(remainOption, prevEntry, nextEntry);
261→                }
262→            }
263→        }
264→        return qinx;
265→    }
266→
267→    private int ruleXEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
268→        if (qinx > 0 && qinx + 1 < queue.size()) {
269→            RuleEntry prevEntry = queue.get(qinx - 1);
270→            RuleEntry nextEntry = queue.get(qinx + 1);
271→            /**
272→             * 숫자x숫자 는 분리하고 x 제거
273→             * 예:
274→             * 100x100, 100x100cm, 100cmx100cm = 숫자x숫자규칙
275→             * 100cmx100 = 모델명규칙
276→             **/
277→            if (isConnected(prevEntry, currentEntry) && isConnected(currentEntry, nextEntry)
278→                    && isEntryType(prevEntry, NUMBER, NUMBER_TRANS, UNIT, UNIT_ALPHA))
279→            {
280→                // 마지막 체크. 앞 뒤로 영숫자 특수문자가 있다면 취소하지 않는다.
281→                boolean flag = false;
282→                /**
283→                 * 숫자x숫자 뒤에 모델명으로 붙을수 있는 문자열 체크
284→                 * 120cmx60cm -> 120cm, 60cm (단위)
285→                 * 120x60cm -> 120, 60cm (단위)
286→                 * 120cmx60 -> 120cm, 60 (단위)
287→                 * 1234x567 -> 1234, 567 (단위)
288→                 * 118X71WXU3 -> 118, X, 71, WXU, 3 (모델명)
289→                 * AB118X71 -> AB, 118, X, 71 (모델명)
290→                 * 숫자x숫자x숫자....식으로 연계될수 있으므로 반복문으로 처리.
291→                 **/
292→                /* 숫자x숫자x숫자.. 식의 연속이 발견되면 건너뜀 */
293→                int xinx = qinx + 2;
294→
295→                for (; xinx < queue.size() - 1; xinx += 2) {
296→                    RuleEntry prevEntryL = queue.get(xinx - 1);
297→                    RuleEntry nextEntryL = queue.get(xinx + 1);
298→                    if ((prevEntryL.type == NUMBER || prevEntryL.type == NUMBER_TRANS || prevEntryL.type == UNIT || prevEntryL.type == UNIT_ALPHA) &&
299→                            (nextEntryL.type == NUMBER || nextEntryL.type == NUMBER_TRANS || nextEntryL.type == UNIT || nextEntryL.type == UNIT_ALPHA)) {
300→                        if (logger.isTraceEnabled()) {
301→                            logger.trace("CHECK:{} {} {} {}", currentEntry.makeTerm(null), prevEntryL.makeTerm(null), queue.get(xinx).makeTerm(null), nextEntryL.makeTerm(null));
302→                            logger.trace("INX:{} / {} / {}", qinx, xinx, queue.size());
303→                        }
304→                    } else {
305→                        break;
306→                    }
307→                }
308→                logger.trace("INX:{} / {} / {} / {}", xinx, qinx, remainOption.typeContinuous, remainOption.typeContinuousMerge);
309→                /* 마지막으로 발견된 연속 숫자x숫자 텀 위치로 */
310→                xinx = xinx - 2 + 1;
311→                if (xinx + 1 < queue.size()) {
312→                    RuleEntry currentEntryL = queue.get(xinx);
313→                    RuleEntry nextEntryL = queue.get(xinx + 1);
314→                    if (isConnected(currentEntryL, nextEntryL)) {
315→                        if (nextEntryL.type == ALPHA || nextEntryL.type == NUMBER || nextEntryL.type == NUMBER_TRANS ||
316→                                (nextEntryL.type == SYMBOL && containsChar(AVAIL_SYMBOLS_CONNECTOR, nextEntryL.buf[nextEntryL.start]))) {
317→                            flag = true;
318→                        }
319→                    }
320→                }
321→                /* 숫자x숫자 앞에 모델명으로 붙을수 있는 문자열 체크 */
322→                if (!flag && qinx > 2) {
323→                    RuleEntry prevPrevEntry = queue.get(qinx - 2);
324→                    RuleEntry prevEntryL = queue.get(qinx - 1);
325→                    if (isConnected(prevPrevEntry, prevEntryL)) {
326→                        if (prevPrevEntry.type == ALPHA || prevPrevEntry.type == NUMBER || prevPrevEntry.type == NUMBER_TRANS ||
327→                                (prevPrevEntry.type == SYMBOL && containsChar(AVAIL_SYMBOLS_CONNECTOR, prevPrevEntry.buf[prevPrevEntry.start]))) {
328→                            flag = true;
329→                        }
330→                    }
331→                }
332→                if (!flag) {
333→                    logger.trace("model name cancel 2 / {} / {}", remainOption.typeContinuous, remainOption.typeContinuousMerge);
334→                    for (int rinx = xinx - 1; rinx >= qinx; rinx -= 2) {
335→                        logger.trace("REMOVE:{} {}", rinx, queue.get(rinx));
336→                        if (rinx - 1 > 0) {
337→                            queue.get(rinx - 1).modifiable = false;
338→                        }
339→                        queue.remove(rinx);
340→                        xinx--;
341→                    }
342→                    breakContinuous(remainOption, remainOption.typeContinuous - 1);
343→                    qinx = xinx;
344→                }
345→            }
346→        }
347→        return qinx;
348→    }
349→
350→    private boolean isXEntry(ContinuousOption remainOption, RuleEntry currentEntry) {
351→        return remainOption.type == ALPHA && currentEntry.length == 1 && Character.toLowerCase(currentEntry.buf[currentEntry.start]) == 'x';
352→    }
353→
354→    private void cancelModelName(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
355→        currentEntry.modifiable = false;
356→        queue.get(qinx - 1).modifiable = false;
357→        remainOption.typeContinuous = 0;
358→        remainOption.typeContinuousMerge = 0;
359→        remainOption.isContinue = true;
360→    }
361→
362→    private int cancelModelName(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry prevEntry, RuleEntry nextEntry) {
363→        prevEntry.modifiable = false;
364→        nextEntry.modifiable = false;
365→        queue.remove(qinx);
366→        remainOption.typeContinuous = remainOption.typeContinuousMerge = 0;
367→        remainOption.isContinue = false;
368→        qinx--;
369→        return qinx;
370→    }
371→
372→    private void cancelModelName(ContinuousOption remainOption, RuleEntry prevEntry, RuleEntry nextEntry) {
373→        if (remainOption.isContinue && remainOption.typeContinuous != 0 && remainOption.typeContinuousMerge == 0) {
374→            prevEntry.modifiable = false;
375→            nextEntry.modifiable = false;
376→            breakContinuous(remainOption, remainOption.typeContinuous);
377→        }
378→        // +이후까지 본 상황 이므로 다음 인덱스는 1개의 오차가 생긴다.
379→        remainOption.overIndex = 1;
380→    }
381→
382→    private void breakContinuous(ContinuousOption remainOption, int typeContinuous) {
383→        remainOption.typeContinuousMerge = typeContinuous;
384→        remainOption.typeContinuous = 0;
385→        remainOption.isContinue = false;
386→    }
387→
388→    private RuleEntry initEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx) {
389→        remainOption.typePrev = remainOption.type;
390→        RuleEntry currentEntry = queue.get(qinx);
391→        // 단어사전에 있는 영문단어는 한글로 인식되므로
392→        // 영문단어인 경우 ALPHA 타입으로 전환
393→        // 차후 동일타입 결합에 의해 영문뭉치는
394→        // 결합단어로도 추출됨 (AdditionalTerm)
395→        // FULL_STRING 은 타입전환을 하지 않는다
396→        CharVector cv = currentEntry.makeTerm(null);
397→        if (currentEntry.type != FULL_STRING && getType(cv.charAt(0)) == ALPHA && (option.useForQuery() || (!option.useForQuery() && currentEntry.type != UNIT))) {
398→            if (getTermType(cv) == ALPHA) {
399→                currentEntry.type = ALPHA;
400→            }
401→        }
402→        remainOption.type = currentEntry.type;
403→        remainOption.isContinue = true;
404→        remainOption.typeContinuousMerge = 0;
405→        remainOption.overIndex = 0;
406→
407→        if (currentEntry.type == FULL_STRING) {
408→            remainOption.typeContinuousMerge = remainOption.typeContinuous;
409→            remainOption.typeContinuous = 0;
410→        }
411→
412→        if (logger.isTraceEnabled()) {
413→            logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]));
414→        }
415→
416→        remainOption.isAlphaNumPrev = remainOption.isAlphaNum;
417→        remainOption.isAlphaNum = currentEntry.type == ALPHA || currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS;
418→        return currentEntry;
419→    }
420→
421→    static class ContinuousOption {
422→        int typeContinuous;
423→        int typeContinuousMerge;
424→        int overIndex;
425→        boolean isContinue;
426→        boolean isAlphaNum;
427→        boolean isAlphaNumPrev;
428→        String typePrev;
429→        String type;
430→
431→        ContinuousOption() {
432→            this.typeContinuous = 0;
433→            this.typeContinuousMerge = 0;
434→            this.isAlphaNum = false;
435→            this.type = null;
436→        }
437→    }
438→}

