package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.dict.SetDictionary;
import com.danawa.search.analysis.product.AnalyzerOption;
import com.danawa.util.CharVector;

import java.util.ArrayList;
import java.util.List;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;

public class RuleFour extends Rule {
    public RuleFour(Entry entry, boolean fullExtract, AnalyzerOption option, SetDictionary unitDictionary) {
        super(entry, fullExtract, option);
        this.unitDictionary = unitDictionary;
    }

    @Override
    public void apply(List<RuleEntry> queue) {
        // 엔트리의 연속 사항을 기록하는 객체
        ContinuousOption remainOption = new ContinuousOption();

        for (int qinx = 0; qinx < queue.size(); qinx++) {
            RuleEntry currentEntry = initEntry(queue, remainOption, qinx);

            // 전/후 엔트리를 비교하여, 모델명을 이룰 수 있는 엔트리 탐색
            if (remainOption.isAlphaNum || isSymbolEntry(currentEntry) || isUnitAlphaEntry(currentEntry) || isUnitEntry(currentEntry)) {
                if (qinx == 0) {
                    // NOP
                } else if (qinx < queue.size()) {
                    RuleEntry prevEntry = queue.get(qinx - 1);

                    // 분리어로 분리된 경우
                    if (currentEntry.length == 0 || prevEntry.length == 0) {
                        breakContinuous(remainOption, remainOption.typeContinuous);
                    } else if (isConnected(prevEntry, currentEntry)  && (
                            (
                                // 특수문자는 연달아 나올수 없다.
                                isNotSymbol(currentEntry) && ((remainOption.isAlphaNumPrev) || isUnitAlphaEntry(prevEntry) || (isSymbolEntry(prevEntry) && remainOption.typeContinuous > 0))
                                // 이 단계에서 UNIT은 한글 단위밖에 없으므로 모델명으로 처리하면 안됨
                                && !(isAlphaEntry(prevEntry) && isUnitEntry(currentEntry))
                            ) ||
                            (
                                isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous > 0)) && currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_CONNECTOR, currentEntry.buf[currentEntry.start])
                            ) ||
                                // 영단위는 - 를 만나면 일단 이어질수 있는것으로 본다.
                            (
                                isUnitAlphaEntry(currentEntry) && prevEntry.length == 1 && prevEntry.buf[prevEntry.start] == AVAIL_SYMBOLS[0]
                            )
                              ||
                            (
                                isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous >= 0)) && currentEntry.length == 1 && currentEntry.buf[currentEntry.start] == AVAIL_SYMBOLS[0]
                            )
                              ||
                                // 색인 시 영단위는 / 를 만나면 일단 이어질수 있는것으로 본다.
                            (
                                !option.useForQuery() && isUnitAlphaEntry(currentEntry) && prevEntry.length == 1 && prevEntry.buf[prevEntry.start] == AVAIL_SYMBOLS[2]
                            )
                              ||
                            (
                                !option.useForQuery() && isSymbolEntry(currentEntry) && (remainOption.isAlphaNumPrev || (isUnitAlphaEntry(prevEntry) && remainOption.typeContinuous >= 0)) && currentEntry.length == 1 && currentEntry.buf[currentEntry.start] == AVAIL_SYMBOLS[2])
                            )
                    ) {
                        remainOption.typeContinuous++;
                        remainOption.isContinue = true;
                    } else {
                        // 문자가 끊겼으므로 이전까지의 연결을 머징해주고 클리어한다.
                        breakContinuous(remainOption, remainOption.typeContinuous);
                    }
                }
            } else {
                breakContinuous(remainOption, remainOption.typeContinuous);
            }
            if (logger.isTraceEnabled()) {
                logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / continue:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, remainOption.isContinue, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]));
            }

            // 병합되기 직전의 처리로 병합을 취소할 수 있는. 예외로직을 기재한다.
            if (remainOption.type == UNIT_ALPHA && remainOption.typePrev == UNIT_ALPHA) {
                if(option.useForQuery()){
                    RuleEntry prevEntry = queue.get(qinx - 1);
                    if (isConnected(prevEntry, currentEntry)) {
                        logger.trace("model name cancel 1");
                        cancelModelName(queue, remainOption, qinx, currentEntry);
                    } else {
                        logger.trace("model name break !");
                        remainOption.isContinue = false;
                        remainOption.typePrev = null;
                    }
                } else {
                    logger.trace("model name break !");
                    remainOption.isContinue = false;
                    remainOption.typePrev = null;
                }
            } else if (remainOption.type == SYMBOL && currentEntry.length == 1) {
                qinx = ruleSymbolEntry(queue, remainOption, qinx, currentEntry);
            } else if (remainOption.type == UNIT_ALPHA) {
                ruleUnitAlphaEntry(queue, remainOption, qinx, currentEntry);
            }
            if (remainOption.isContinue) {
                logger.trace("continue..");
                continue;
            }

            // 모델명 조합에 사용된 모든 텀들을 재조합하여 가지고 있는다.
            if (remainOption.typeContinuousMerge > 0) {
                qinx = combineUsedModelNameTerm(queue, remainOption, qinx, currentEntry);
            }
            remainOption.typeContinuousMerge = 0;
        } // for
        if (remainOption.typeContinuous > 0 && remainOption.typeContinuousMerge == 0) {
            remainOption.typeContinuousMerge = remainOption.typeContinuous;
        }
        if (remainOption.typeContinuousMerge > 0) {
            ruleRemainTerm(queue, remainOption);
        }
        logger.trace("4th process complete / queue:{}", queue);
    }

    private void ruleRemainTerm(List<RuleEntry> queue, ContinuousOption remainOption) {
        remainOption.typeContinuousMerge++;
        // 마지막 특수기호는 버린다.
        if (remainOption.type == SYMBOL) {
            queue.remove(queue.size() - 1);
            remainOption.typeContinuousMerge--;
        }
        if (remainOption.typeContinuousMerge > 1) {
            List<RuleEntry> subQueue = null;
            if (fullExtract) {
                subQueue = new ArrayList<>();
            }
            logger.trace("merging.. {} / {} / {}", remainOption.typeContinuousMerge, queue, subQueue);
            RuleEntry entry;
            if(!option.useForQuery()){
                // 색인 시
                entry = Entry.mergeQueueIndex(queue.size(), remainOption.typeContinuousMerge, queue, subQueue);
            } else {
                // 검색 시
                entry = Entry.mergeQueueQuery(queue.size(), remainOption.typeContinuousMerge, queue, subQueue);
            }

            if (entry != null) {
                if (entry.type == null) { entry.type = MODEL_NAME; }
                logger.trace("subQueue:{}", subQueue);

                if (fullExtract) {
                    logger.trace("## MERGE_2 : {} : {}", entry, subQueue);
                    Entry.mergeSubQueue(entry, subQueue, option, unitDictionary);
                    if (subQueue.size() > 1) {
                        entry.subEntry = subQueue;
                    }
                    logger.trace("entry:{} / subQueue:{}", entry, entry.subEntry);
                }
            }
        }
    }

    private int combineUsedModelNameTerm(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
        remainOption.typeContinuousMerge++;
        // 마지막 특수기호는 버린다.
        if (remainOption.type == SYMBOL) {
            // 독립기호가 아닌경우에만 버리도록
            if (!(currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_STANDALONE, currentEntry.buf[currentEntry.start]))) {
                queue.remove(qinx);
            }
        }

        if (remainOption.typeContinuousMerge > 1) {
            List<RuleEntry> subQueue = null;
            if (fullExtract) {
                subQueue = new ArrayList<>();
            }
            logger.trace("merging..qinx:{} / tcont:{}", qinx, remainOption.typeContinuousMerge);
            RuleEntry entry;
            if(!option.useForQuery()){
                // 색인 시
                entry = Entry.mergeQueueIndex(qinx, remainOption.typeContinuousMerge, queue, subQueue);
            } else {
                // 검색 시
                entry = Entry.mergeQueueQuery(qinx, remainOption.typeContinuousMerge, queue, subQueue);
            }

            if (entry != null) {
                if (entry.type == null) { entry.type = MODEL_NAME; }
                logger.trace("qinx:{} / typeContinuousMerge:{} / overIndex:{}", qinx, remainOption.typeContinuousMerge, remainOption.overIndex);
                qinx -= remainOption.typeContinuousMerge;
                logger.trace("qinx:{}", qinx);
                qinx -= remainOption.overIndex;
                if (fullExtract) {
                    logger.trace("## MERGE_1 : {} : {}", entry, subQueue);
                    Entry.mergeSubQueue(entry, subQueue, option, unitDictionary);
                    if (subQueue.size() > 1) {
                        entry.subEntry = subQueue;
                    }
                    logger.trace("entry:{} / subQueue:{}", entry, entry.subEntry);
                    logger.trace("## Q[{}] : {}", qinx, queue);
                }
            }
        }
        return qinx;
    }

    private void ruleUnitAlphaEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
        RuleEntry prevEntry = null;
        RuleEntry nextEntry = null;
        if (qinx > 0) {
            prevEntry = queue.get(qinx - 1);
        }
        if (qinx + 1 < queue.size()) {
            nextEntry = queue.get(qinx + 1);
        }
        if (prevEntry != null && (currentEntry.start != prevEntry.start + prevEntry.length)) {
            // 붙이지 않는다.
            remainOption.typeContinuous = 0;
            remainOption.isContinue = false;
        } else if(prevEntry != null && nextEntry != null
                && (isSymbolEntry(prevEntry) && !(isAlphaEntry(nextEntry) || isNumberEntry(nextEntry))
                || isSymbolEntry(nextEntry) && !(isAlphaEntry(prevEntry) || isNumberEntry(prevEntry)))
        ) {
            // 단위명 앞 뒤로 기호일 경우는 일단 모델명에서 제외, 단위명 우선.
            // 단 단위가 연결자일 경우는 모델명 우선.
            // 한쪽이라도 - 연결자가 발견되면 다시 모델명으로 인식.
            if (!(prevEntry.buf[prevEntry.start] == '-' || nextEntry.buf[nextEntry.start] == '-')) {
                currentEntry.modifiable = false;
                if (remainOption.typeContinuous > 0) {
                    logger.trace("model name cancel 6");
                    breakContinuous(remainOption, remainOption.typeContinuous - 1);
                } else {
                    remainOption.typeContinuous = 0;
                    remainOption.isContinue = true;
                }
            } else {
                remainOption.isContinue = false;
            }
        }
    }

    private int ruleSymbolEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
        if (currentEntry.buf[currentEntry.start] == '/' && option.useForQuery()) {
            // 숫자 사이의 / 는 삭제
            if (qinx > 0 && qinx + 1 < queue.size()) {
                RuleEntry prevEntry = queue.get(qinx - 1);
                RuleEntry nextEntry = queue.get(qinx + 1);
                if (isConnected(prevEntry ,currentEntry) && isConnected(currentEntry, nextEntry)
                        && (isNumberEntry(prevEntry) && isNumberEntry(nextEntry))) {
                    // 단일숫자일 경우에만 / 삭제
                    if (remainOption.typeContinuous < 2) {
                        logger.trace("model name cancel 3");
                        qinx = cancelModelName(queue, remainOption, qinx, prevEntry, nextEntry);
                    }
                }
            }
        } else if (currentEntry.buf[currentEntry.start] == '+' && option.useForQuery()) {
            // + 로 이어진 모델명들은 취소한다.
            if (qinx > 0 && qinx + 1 < queue.size()) {
                RuleEntry prevEntry = queue.get(qinx - 1);
                RuleEntry nextEntry = queue.get(qinx + 1);
                if (isConnected(prevEntry, currentEntry) && isConnected(currentEntry, nextEntry)) {
                    logger.trace("model name cancel 4 / {}:{}", remainOption.typeContinuous, remainOption.typeContinuousMerge);
                    cancelModelName(remainOption, prevEntry, nextEntry);
                }
            }
        }
        return qinx;
    }

    private int ruleXEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
        if (qinx > 0 && qinx + 1 < queue.size()) {
            RuleEntry prevEntry = queue.get(qinx - 1);
            RuleEntry nextEntry = queue.get(qinx + 1);
            /**
             * 숫자x숫자 는 분리하고 x 제거
             * 예:
             * 100x100, 100x100cm, 100cmx100cm = 숫자x숫자규칙
             * 100cmx100 = 모델명규칙
             **/
            if (isConnected(prevEntry, currentEntry) && isConnected(currentEntry, nextEntry)
                    && isEntryType(prevEntry, NUMBER, NUMBER_TRANS, UNIT, UNIT_ALPHA))
            {
                // 마지막 체크. 앞 뒤로 영숫자 특수문자가 있다면 취소하지 않는다.
                boolean flag = false;
                /**
                 * 숫자x숫자 뒤에 모델명으로 붙을수 있는 문자열 체크
                 * 120cmx60cm -> 120cm, 60cm (단위)
                 * 120x60cm -> 120, 60cm (단위)
                 * 120cmx60 -> 120cm, 60 (단위)
                 * 1234x567 -> 1234, 567 (단위)
                 * 118X71WXU3 -> 118, X, 71, WXU, 3 (모델명)
                 * AB118X71 -> AB, 118, X, 71 (모델명)
                 * 숫자x숫자x숫자....식으로 연계될수 있으므로 반복문으로 처리.
                 **/
                /* 숫자x숫자x숫자.. 식의 연속이 발견되면 건너뜀 */
                int xinx = qinx + 2;

                for (; xinx < queue.size() - 1; xinx += 2) {
                    RuleEntry prevEntryL = queue.get(xinx - 1);
                    RuleEntry nextEntryL = queue.get(xinx + 1);
                    if ((prevEntryL.type == NUMBER || prevEntryL.type == NUMBER_TRANS || prevEntryL.type == UNIT || prevEntryL.type == UNIT_ALPHA) &&
                            (nextEntryL.type == NUMBER || nextEntryL.type == NUMBER_TRANS || nextEntryL.type == UNIT || nextEntryL.type == UNIT_ALPHA)) {
                        if (logger.isTraceEnabled()) {
                            logger.trace("CHECK:{} {} {} {}", currentEntry.makeTerm(null), prevEntryL.makeTerm(null), queue.get(xinx).makeTerm(null), nextEntryL.makeTerm(null));
                            logger.trace("INX:{} / {} / {}", qinx, xinx, queue.size());
                        }
                    } else {
                        break;
                    }
                }
                logger.trace("INX:{} / {} / {} / {}", xinx, qinx, remainOption.typeContinuous, remainOption.typeContinuousMerge);
                /* 마지막으로 발견된 연속 숫자x숫자 텀 위치로 */
                xinx = xinx - 2 + 1;
                if (xinx + 1 < queue.size()) {
                    RuleEntry currentEntryL = queue.get(xinx);
                    RuleEntry nextEntryL = queue.get(xinx + 1);
                    if (isConnected(currentEntryL, nextEntryL)) {
                        if (nextEntryL.type == ALPHA || nextEntryL.type == NUMBER || nextEntryL.type == NUMBER_TRANS ||
                                (nextEntryL.type == SYMBOL && containsChar(AVAIL_SYMBOLS_CONNECTOR, nextEntryL.buf[nextEntryL.start]))) {
                            flag = true;
                        }
                    }
                }
                /* 숫자x숫자 앞에 모델명으로 붙을수 있는 문자열 체크 */
                if (!flag && qinx > 2) {
                    RuleEntry prevPrevEntry = queue.get(qinx - 2);
                    RuleEntry prevEntryL = queue.get(qinx - 1);
                    if (isConnected(prevPrevEntry, prevEntryL)) {
                        if (prevPrevEntry.type == ALPHA || prevPrevEntry.type == NUMBER || prevPrevEntry.type == NUMBER_TRANS ||
                                (prevPrevEntry.type == SYMBOL && containsChar(AVAIL_SYMBOLS_CONNECTOR, prevPrevEntry.buf[prevPrevEntry.start]))) {
                            flag = true;
                        }
                    }
                }
                if (!flag) {
                    logger.trace("model name cancel 2 / {} / {}", remainOption.typeContinuous, remainOption.typeContinuousMerge);
                    for (int rinx = xinx - 1; rinx >= qinx; rinx -= 2) {
                        logger.trace("REMOVE:{} {}", rinx, queue.get(rinx));
                        if (rinx - 1 > 0) {
                            queue.get(rinx - 1).modifiable = false;
                        }
                        queue.remove(rinx);
                        xinx--;
                    }
                    breakContinuous(remainOption, remainOption.typeContinuous - 1);
                    qinx = xinx;
                }
            }
        }
        return qinx;
    }

    private boolean isXEntry(ContinuousOption remainOption, RuleEntry currentEntry) {
        return remainOption.type == ALPHA && currentEntry.length == 1 && Character.toLowerCase(currentEntry.buf[currentEntry.start]) == 'x';
    }

    private void cancelModelName(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry currentEntry) {
        currentEntry.modifiable = false;
        queue.get(qinx - 1).modifiable = false;
        remainOption.typeContinuous = 0;
        remainOption.typeContinuousMerge = 0;
        remainOption.isContinue = true;
    }

    private int cancelModelName(List<RuleEntry> queue, ContinuousOption remainOption, int qinx, RuleEntry prevEntry, RuleEntry nextEntry) {
        prevEntry.modifiable = false;
        nextEntry.modifiable = false;
        queue.remove(qinx);
        remainOption.typeContinuous = remainOption.typeContinuousMerge = 0;
        remainOption.isContinue = false;
        qinx--;
        return qinx;
    }

    private void cancelModelName(ContinuousOption remainOption, RuleEntry prevEntry, RuleEntry nextEntry) {
        if (remainOption.isContinue && remainOption.typeContinuous != 0 && remainOption.typeContinuousMerge == 0) {
            prevEntry.modifiable = false;
            nextEntry.modifiable = false;
            breakContinuous(remainOption, remainOption.typeContinuous);
        }
        // +이후까지 본 상황 이므로 다음 인덱스는 1개의 오차가 생긴다.
        remainOption.overIndex = 1;
    }

    private void breakContinuous(ContinuousOption remainOption, int typeContinuous) {
        remainOption.typeContinuousMerge = typeContinuous;
        remainOption.typeContinuous = 0;
        remainOption.isContinue = false;
    }

    private RuleEntry initEntry(List<RuleEntry> queue, ContinuousOption remainOption, int qinx) {
        remainOption.typePrev = remainOption.type;
        RuleEntry currentEntry = queue.get(qinx);
        // 단어사전에 있는 영문단어는 한글로 인식되므로
        // 영문단어인 경우 ALPHA 타입으로 전환
        // 차후 동일타입 결합에 의해 영문뭉치는
        // 결합단어로도 추출됨 (AdditionalTerm)
        // FULL_STRING 은 타입전환을 하지 않는다
        CharVector cv = currentEntry.makeTerm(null);
        if (currentEntry.type != FULL_STRING && getType(cv.charAt(0)) == ALPHA && (option.useForQuery() || (!option.useForQuery() && currentEntry.type != UNIT))) {
            if (getTermType(cv) == ALPHA) {
                currentEntry.type = ALPHA;
            }
        }
        remainOption.type = currentEntry.type;
        remainOption.isContinue = true;
        remainOption.typeContinuousMerge = 0;
        remainOption.overIndex = 0;

        if (currentEntry.type == FULL_STRING) {
            remainOption.typeContinuousMerge = remainOption.typeContinuous;
            remainOption.typeContinuous = 0;
        }

        if (logger.isTraceEnabled()) {
            logger.trace("qinx:{} / type:{} / typePrev:{} / typeCont:{} / e0:{} / char:[{}]:{}", qinx, remainOption.type, remainOption.typePrev, remainOption.typeContinuous, currentEntry, currentEntry.buf[currentEntry.start], containsChar(AVAIL_SYMBOLS_INNUMBER, currentEntry.buf[currentEntry.start]));
        }

        remainOption.isAlphaNumPrev = remainOption.isAlphaNum;
        remainOption.isAlphaNum = currentEntry.type == ALPHA || currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS;
        return currentEntry;
    }

    static class ContinuousOption {
        int typeContinuous;
        int typeContinuousMerge;
        int overIndex;
        boolean isContinue;
        boolean isAlphaNum;
        boolean isAlphaNumPrev;
        String typePrev;
        String type;

        ContinuousOption() {
            this.typeContinuous = 0;
            this.typeContinuousMerge = 0;
            this.isAlphaNum = false;
            this.type = null;
        }
    }
}

